"""Build 100 original grade-nine OGE word problems with worked solutions."""
import json
from pathlib import Path

OUT=Path(__file__).resolve().parents[1]/'dist'/'oge-word-problems.js'
SRC_MOTION=[314507,314516,314561,314566,314593,314606,333023,333102,333128,333155,338854,338998,341283,341288,353306,353554,353577,384415,348526,348607,348624,348814,348902,348978,349007]
SRC_WATER=[311564,341158,311570,341227,341341,341419,349847,350672,351294,352282,353433,353507,348472,348506,348608]
SRC_WORK=[311966,338706,348479,349199,349586,350909,352964,348754,350273,350275,350318,350870,351170,351450,351617,351887,352208,352264,352315,352695]
SRC_MIX=[314457,314431,314469,314480,348438,349691,349497,349700,349844,350150,350236,351603,351824,352466,392854,392880,400982,401741,401878,401884,401970,402199,402262,403153,403266]
SRC_PERCENT=[43,340593,341335,355419,355393,355445,356253,356254,356255,356256,356257,356258,356259,356260,356261]
bank=[]
def add(title,question,answer,steps,hints,plan,verify,trap,source_id,category,source_type):
    n=len(bank)+1
    bank.append({'id':f'oge-word-problems-{n}','exam':'oge','domain':'math','grade':9,'subject':'algebra','topicName':'Текстовые задачи','topic':7,'examTopic':'word-problems','level':0,'challenge':False,'goal':'ОГЭ · текстовые задачи','title':title,'question':question,'answer':float(answer),'hints':hints,'steps':steps,'review':{'plan':plan,'verify':verify,'trap':trap},'source':{'name':'Решу ОГЭ','id':source_id,'type':source_type,'url':f'https://math-oge.sdamgia.ru/problem?id={source_id}','note':'Авторская задача Матклуба по теме; ссылка ведёт к соответствующему разделу каталога «Решу ОГЭ».'}})

# 1–10: catching up on a straight road.
for i in range(10):
    slow=36+3*i; fast=slow+12+3*(i%3); time=2+i%5; lead=(fast-slow)*time
    distance=fast*time
    question=f'Велосипедист едет со скоростью {slow} км/ч. Через {time} ч после его старта вслед за ним выезжает мотоциклист со скоростью {fast} км/ч. Какое расстояние проедет мотоциклист до встречи?'
    steps=[f'Скорость сближения равна {fast}−{slow} = {fast-slow} км/ч.',f'Фора велосипедиста за {time} ч: {slow}·{time} = {lead} км.',f'Время погони: {lead}/{fast-slow} = {time} ч. Тогда путь мотоциклиста {fast}·{time} = {distance} км.']
    add('Движение вдогонку',question,distance,steps,['Сначала найди скорость сближения: разность скоростей.','Время погони отсчитывается от старта второго участника.'], 'При движении вдогонку скорость сближения равна разности скоростей.','В момент встречи оба участника прошли одинаковое расстояние от точки старта второго: это можно проверить с учётом форы.','Не умножай скорость мотоциклиста на всё время с момента старта велосипедиста.',SRC_MOTION[i],22,'Движение по прямой')

# 11–25: boat speed, current, and meeting traffic.
for i in range(15):
    if i<10:
        still=12+i; current=2+(i%4); distance=(still-current)*(2+i%4)
        direction='против течения'; speed=still-current; time=distance//speed
        question=f'Скорость катера в стоячей воде {still} км/ч, скорость течения {current} км/ч. Сколько часов катер затратит на путь {distance} км {direction}?'
        steps=[f'Против течения скорость катера равна {still}−{current} = {speed} км/ч.',f'Время равно расстоянию, делённому на скорость: {distance}/{speed} = {time} ч.']
        ans=time; source=SRC_WATER[i]
        add('Движение по воде',question,ans,steps,['Для движения против течения вычти скорость течения из собственной скорости катера.','Время = путь / скорость.'], 'Сначала вычисли скорость относительно берега, затем примени формулу пути.',f'{speed}·{time} = {distance} км.','Скорость течения прибавляют только при движении по течению.',source,76,'Задачи на движение по воде')
    else:
        k=i-10; v1=40+5*k; v2=50+5*(k%3); time=2+k%4; gap=(v1+v2)*time
        question=f'Два автомобиля выехали одновременно навстречу друг другу из пунктов на расстоянии {gap} км. Их скорости {v1} км/ч и {v2} км/ч. Через сколько часов они встретятся?'
        steps=[f'При движении навстречу скорость сближения равна сумме скоростей: {v1}+{v2} = {v1+v2} км/ч.',f'Время до встречи: {gap}/{v1+v2} = {time} ч.']
        add('Встречное движение',question,time,steps,['При движении навстречу расстояния, пройденные участниками, складываются.','Скорость сближения — сумма скоростей.'],'Составь уравнение: (v₁+v₂)t равно расстоянию между пунктами.',f'За {time} ч автомобили пройдут {v1*time} км и {v2*time} км; сумма равна {gap} км.','Для движения в противоположных направлениях используй сумму скоростей.',SRC_MOTION[10+k],22,'Движение по прямой')

# 26–45: joint work and filling/emptying.
work_pairs=[(6,3,2),(4,12,3),(8,8,4),(5,20,4),(6,6,3),(12,4,3),(8,8,4),(12,6,4),(8,8,4),(20,5,4)]
for i in range(20):
    a,b,t=work_pairs[i%len(work_pairs)]
    if i%4==0:
        question=f'Первый рабочий выполняет заказ за {a} ч, второй — за {b} ч. За сколько часов они выполнят заказ вместе?'
        rate=f'За час первый выполняет 1/{a} заказа, второй — 1/{b}. Вместе: 1/{a}+1/{b} = {1/a+1/b:g} заказа за час.'
        ans=t; steps=[rate,f'Общее время равно 1 / ({1/a+1/b:g}) = {ans} ч.']
    elif i%4==1:
        hours=1+(i%2); done=hours*(1/a+1/b)
        ans=round(done*1000)/1000
        question=f'Два насоса наполняют резервуар за {a} ч и {b} ч соответственно. Какую часть резервуара они наполнят за {hours} ч совместной работы?'
        steps=[f'За час насосы наполняют 1/{a}+1/{b} = {1/a+1/b:g} резервуара.',f'За {hours} ч они наполнят {hours}·({1/a+1/b:g}) = {ans:g} резервуара.']
    elif i%4==2:
        # Derive unknown time from a known combined time chosen to yield integer b.
        first=a; second=b; combined=1/(1/first+1/second)
        ans=second
        question=f'Один мастер выполняет заказ за {first} ч. Вместе со вторым мастером заказ выполняется за {combined:g} ч. За сколько часов второй мастер выполнит заказ один?'
        steps=[f'Производительность вместе: 1/{combined:g} заказа в час; первого мастера: 1/{first}.',f'Производительность второго: 1/{combined:g}−1/{first} = {1/second:g} заказа в час.',f'Значит, второму мастеру одному нужно {ans} ч.']
    else:
        amount=2+i%5; ans=amount*(1/a+1/b)
        question=f'Два принтера печатают со скоростями 1/{a} и 1/{b} заказа в час. Какую часть заказа они напечатают за {amount} ч, работая одновременно?'
        steps=[f'Общая скорость: 1/{a}+1/{b} = {1/a+1/b:g} заказа в час.',f'За {amount} ч будет выполнено {amount}·({1/a+1/b:g}) = {ans:g} заказа.']
    add('Совместная работа',question,ans,steps,['Сложи производительности, а не времена выполнения работы.','Производительность — это часть работы за один час.'],'Переведи время выполнения всей работы в скорость за один час.',f'Суммарная производительность согласуется с найденным временем или объёмом работы: {ans:g}.','Время совместной работы не равно сумме времени каждого исполнителя.',SRC_WORK[i],77,'Задачи на совместную работу')

# 46–65: solution mixtures, dilution, evaporation, and alloy concentrations.
for i in range(20):
    m,c1,target,c2=[(200,10,20,30),(300,10,25,40),(400,15,25,35),(600,20,30,40)][i%4]
    mode=i%4
    if mode==0:
        x=m*(target-c1)//(c2-target)
        question=f'Есть {m} г раствора с концентрацией {c1}%. Сколько граммов вещества с концентрацией {c2}% нужно добавить, чтобы получить смесь с концентрацией {target}%?'
        sol=m*c1/100; xsol=x*c2/100
        steps=[f'В исходном растворе вещества {m}·{c1}/100 = {sol:g} г.',f'Составляем баланс: ({sol:g}+{c2}x/100)/({m}+x) = {target}/100.',f'После умножения и переноса: ({c2-target})x = {m*(target-c1)}, откуда x = {x} г.']
        ans=x; title='Смешивание растворов'
    elif mode==1:
        final=m*c1//target; ans=final-m
        question=f'В {m} г раствора содержится {c1}% вещества. Сколько граммов воды нужно добавить, чтобы концентрация стала {target}%?'
        steps=[f'Масса растворённого вещества неизменна: {m}·{c1}/100 = {m*c1/100:g} г.',f'При концентрации {target}% масса раствора должна быть {m*c1/target} г.',f'Добавить нужно {m*c1/target}−{m} = {ans} г воды.']
        title='Разбавление раствора'
    elif mode==2:
        final=m*c1//target; ans=m-final
        question=f'Раствор массой {m} г имеет концентрацию {c1}%. Сколько граммов воды нужно выпарить, чтобы концентрация вещества стала {target}%?'
        steps=[f'Масса вещества равна {m}·{c1}/100 = {m*c1/100:g} г и при выпаривании не меняется.',f'Искомая конечная масса: {m*c1/target} г.',f'Выпарить надо {m}−{m*c1/target} = {ans} г воды.']
        title='Изменение концентрации выпариванием'
    else:
        x=m*(target-c1)//(c2-target)
        question=f'Смешали {m} г сплава с содержанием меди {c1}% и сплав с содержанием меди {c2}%. Получили сплав с содержанием меди {target}%. Какова масса второго сплава?'
        steps=[f'Меди в первом сплаве {m}·{c1}/100 = {m*c1/100:g} г.',f'Записываем баланс меди: ({m*c1/100:g}+{c2}x/100)/({m}+x) = {target}/100.',f'Решение линейного уравнения даёт x = {x} г.']
        ans=x; title='Смешивание сплавов'
    add(title,question,ans,steps,['Сохраняется масса растворённого вещества или металла.','Составь уравнение: масса чистого вещества до смешивания равна массе после.'],'Вырази массу чистого вещества через массу смеси и процент концентрации.',f'После операции масса чистого вещества остаётся {m*c1/100:g} г плюс вклад добавленного материала, если он есть.','Не складывай проценты напрямую: используй взвешенную сумму по массам.',SRC_MIX[i],79,'Задачи на проценты, сплавы и смеси')

# 66–80: price changes and percentages in practical settings.
for i in range(15):
    original=800+100*i; pct=10+5*(i%5); final=original*(100-pct)//100
    mode=i%3
    if mode==0:
        question=f'Куртка после скидки {pct}% стоит {final} рублей. Сколько рублей она стоила до скидки?'
        steps=[f'После скидки осталось {100-pct}% исходной цены.',f'Обозначим старую цену x: x·({100-pct})/100 = {final}.',f'x = {final}·100/{100-pct} = {original} рублей.']; ans=original; title='Найти цену до скидки'
    elif mode==1:
        up=10+5*(i%4); new=original*(100+up)//100
        question=f'Цена товара {original} рублей сначала выросла на {up}%, а затем снизилась на {pct}%. Какой стала цена?'
        steps=[f'После повышения цена: {original}·{100+up}/100 = {new} рублей.',f'Снижаем уже новую цену: {new}·{100-pct}/100 = {new*(100-pct)//100} рублей.']
        ans=new*(100-pct)//100; title='Последовательные изменения цены'
    else:
        part=original*pct//100
        question=f'Магазин продал {original} одинаковых товаров. {pct}% из них продали утром. Сколько товаров осталось продать?'
        steps=[f'Утром продали {original}·{pct}/100 = {part} товаров.',f'Осталось {original}−{part} = {original-part} товаров.'];ans=original-part;title='Процент от количества'
    add(title,question,ans,steps,['Найди, от какой величины берётся процент.','При последовательных изменениях каждый процент считают от новой цены.'],'Переведи процент в множитель и составь уравнение или вычисление.',f'Обратная проверка: рассчитанная величина соответствует условию; ответ {ans}.','Скидка на цену после повышения считается от уже изменённой цены.',SRC_PERCENT[i],17,'Проценты')

# 81–100: ages, digit problems, and proportional models.
for i in range(20):
    mode=i%4
    if mode==0:
        child=5+i%8; parent=3*child; years=child; ans=child
        question=f'Сейчас отец в 3 раза старше сына. Через {years} лет возраст отца будет в 2 раза больше возраста сына. Сколько лет сыну сейчас?'
        steps=[f'Обозначим нынешний возраст сына через x, тогда отцу 3x.',f'Через {years} лет: 3x+{years} = 2(x+{years}).',f'Решаем: x = {ans}. Проверка: через {years} лет сыну {child+years}, отцу {parent+years}; отец вдвое старше.'];title='Задача на возраст'
    elif mode==1:
        tens=5+i%4; units=tens-(1+i%4); number=10*tens+units; rev=10*units+tens; ans=number
        question=f'Двузначное число в {number-rev} больше числа, записанного теми же цифрами в обратном порядке. Сумма цифр равна {tens+units}. Найди исходное число.'
        steps=[f'Пусть десятки равны a, единицы — b. Тогда a+b = {tens+units}.',f'Разность чисел (10a+b)−(10b+a) = 9(a−b) = {number-rev}, значит a−b = {(number-rev)//9}.',f'Решаем систему: a={tens}, b={units}. Исходное число {ans}.'];title='Задача на запись числа цифрами'
    elif mode==2:
        x=15+i; other=2*(x+3); ans=x
        question=f'Первое число на 3 меньше половины второго. Сумма чисел равна {x+other}. Найди первое число.'
        steps=[f'Пусть первое число x. Тогда второе равно 2(x+3).',f'x+2(x+3) = {x+other}; 3x+6 = {x+other}.',f'Решаем: x = {ans}.'];title='Составление уравнения по условию'
    else:
        ratio=2+i%4; ans=15+i; total=(ratio+1)*ans; other=ratio*ans
        question=f'Две группы собрали {total} кг макулатуры. Во второй группе собрали в {ratio} раза больше, чем в первой. Сколько килограммов собрала первая группа?'
        steps=[f'Пусть первая группа собрала x кг, тогда вторая — {ratio}x кг.',f'x+{ratio}x = {total}, откуда x = {total}/{ratio+1} = {ans} кг.'];title='Задача на отношение величин'
    add(title,question,ans,steps,['Обозначь неизвестную величину переменной.','Переведи слова «на ... больше», «в ... раза» и «сумма» в уравнение.'],'Задай переменную для одной величины и вырази через неё остальные.',f'Подстановка найденного значения удовлетворяет исходному условию; ответ {ans}.','«На несколько единиц больше» означает прибавление, а «в несколько раз больше» — умножение.',SRC_MOTION[(i+5)%len(SRC_MOTION)],22,'Текстовые задачи')

assert len(bank)==100
assert len({t['id'] for t in bank})==100
OUT.write_text('/* 100 авторских задач ОГЭ по текстовым моделям. */\n(()=>{const bank='+json.dumps(bank,ensure_ascii=False,separators=(',',':'))+';for(const item of bank)tasks.push(item)})();\n',encoding='utf-8')
print(f'Wrote {len(bank)} OGE word problems to {OUT}')
